// 899371 enrichment P14 (docs/enterprise-899371-enrichment-plan.md §3.3, §11) — the «حلّ وافحص» INDEX of a learning course
// (api/src/data/learning-solve/<courseId>.json, generated by scripts/build-learning-solve-index.mjs from questions proven by RUNNING
// their reference and known-wrong solutions). Server-side only. Per writing question of the book:
//   • `node` — the coding question's PUBLIC projection (starter or locked template, the public example with its output, the limits):
//     what the editor may show;
//   • `hidden` — inputs and expected outputs of the check: NEVER sent; the check returns pass / fail per hidden input only;
//   • `reference` + `explanation` — the solution card: sent only when the policy allows it for this reader (decision D1).
// Pure readers and the source builder; the route decides who may do what.
const { reconstructTemplateSource } = require("./shared-finalization/codingTemplate");
const { CODE_SOURCE_MAX_BYTES } = require("./shared-finalization/codingQuestion");

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const cleanId = v => String(v || "").trim();
const CACHE = new Map();
const SOURCE_MAX_BYTES = 16384;
const GAP_MAX_BYTES = 8192;

/** The course's solve index, or null (no index / malformed). Cached per process. */
function loadSolveIndex(courseId) {
  const id = cleanId(courseId);
  if (!ID.test(id)) return null;
  if (CACHE.has(id)) return CACHE.get(id);
  let index = null;
  try { index = require("../data/learning-solve/" + id + ".json"); } catch { index = null; }
  if (!index || index.schemaVersion !== 1 || index.courseId !== id || !index.questions || typeof index.questions !== "object") index = null;
  CACHE.set(id, index);
  return index;
}

/** One question by its id, or null (unknown ids are never echoed). */
function findSolve(index, questionId) {
  const q = cleanId(questionId);
  if (!index || !ID.test(q) || !Object.prototype.hasOwnProperty.call(index.questions, q)) return null;
  const s = index.questions[q];
  return s && typeof s === "object" && typeof s.moduleId === "string" && s.node && typeof s.node === "object" ? s : null;
}

/** What the editor may show of a question (never `hidden`, `reference` or `explanation`). */
function publicView(questionId, s, solutionOpen) {
  return { questionId, number: s.number, version: s.version, check: s.check === true, ...(s.title ? { title: s.title } : {}), ...(s.text ? { text: s.text } : {}),
    node: s.node, solution: solutionOpen ? "open" : "locked" };
}

/**
 * The program a learner's answer IS, built only from what the question allows: a whole program (version 2: `source`, ≤ 16 KB, not
 * blank) or the PUBLISHED locked template with the learner's gap values (version 3: `values`, one string per editable gap, each
 * ≤ 8 KB; locked text can never come from the request). → { ok, source } or { ok: false, code }.
 */
function programFromAnswer(s, body) {
  if (s.version === 3) {
    const t = s.node && s.node.template;
    if (!t || !Array.isArray(t.segments)) return { ok: false, code: "REQUEST_INVALID" };
    const v = body && body.values;
    if (!v || typeof v !== "object" || Array.isArray(v)) return { ok: false, code: "REQUEST_INVALID" };
    const gaps = t.segments.filter(g => g.kind === "editable").map(g => g.id);
    const keys = Object.keys(v);
    if (keys.length !== gaps.length || !keys.every(k => gaps.includes(k)) || !keys.every(k => typeof v[k] === "string")) return { ok: false, code: "REQUEST_INVALID" };
    if (keys.some(k => Buffer.byteLength(v[k], "utf8") > GAP_MAX_BYTES)) return { ok: false, code: "TOO_LARGE" };
    const source = reconstructTemplateSource({ language: "csharp", segments: t.segments }, v);
    // the whole program (locked text + every gap) within the Runner's source limit, refused here rather than after the bucket
    if (Buffer.byteLength(source, "utf8") > CODE_SOURCE_MAX_BYTES) return { ok: false, code: "TOO_LARGE" };
    return { ok: true, source };
  }
  const src = body && body.source;
  if (typeof src !== "string") return { ok: false, code: "REQUEST_INVALID" };
  if (Buffer.byteLength(src, "utf8") > SOURCE_MAX_BYTES) return { ok: false, code: "TOO_LARGE" };
  if (!src.trim()) return { ok: false, code: "SOURCE_EMPTY" };
  return { ok: true, source: src };
}

module.exports = { loadSolveIndex, findSolve, publicView, programFromAnswer, SOURCE_MAX_BYTES, GAP_MAX_BYTES };
